// Parse the chat message to extract the related Jira story key and the raw bug description.
// Expected format: "KAN-1: promo code field does not trim leading spaces..."
const input = $json.chatInput || '';

const keyMatch = input.match(/\b([A-Z][A-Z0-9]+-\d+)\b/);
const storyKey = keyMatch ? keyMatch[1] : null;
const projectKey = storyKey ? storyKey.split('-')[0] : null;

let rawBugDescription = input;
if (keyMatch) {
  rawBugDescription = input.replace(keyMatch[0], '').replace(/^[:\-\s]+/, '').trim();
}

return [{
  json: {
    storyKey,
    projectKey,
    rawBugDescription
  }
}];

const bug = $input.item.json.output;
const storyKey = $('Parse Story Key & Bug Text').item.json.storyKey;

let revisionCount = 0;
try {
  const prevCtx = $('Prepare Revision Context').first();
  if (prevCtx && prevCtx.json && typeof prevCtx.json.revisionCount === 'number') {
    revisionCount = prevCtx.json.revisionCount;
  }
} catch (e) {
  revisionCount = 0;
}
const maxRevisions = 3;

let description = `*Steps to Reproduce:*\n${bug.stepsToReproduce}\n\n`;
description += `*Expected Result:*\n${bug.expectedResult}\n\n`;
description += `*Actual Result:*\n${bug.actualResult}\n\n`;
description += `*Severity:* ${bug.severity} - ${bug.severityJustification}\n\n`;
if (storyKey) {
  description += `*Related Story:* ${storyKey}\n`;
}
description += `\n_This bug report was drafted by the Smart Bug Report Agent and reviewed by a human before creation._`;

return [{
  json: {
    title: bug.title,
    description,
    stepsToReproduce: bug.stepsToReproduce,
    expectedResult: bug.expectedResult,
    actualResult: bug.actualResult,
    severity: bug.severity,
    severityJustification: bug.severityJustification,
    storyKey,
    revisionCount,
    maxRevisions
  }
}];

const form = $input.item.json;

const revisionCount = Number(form['Revision Count']) || 0;
const maxRevisions = Number(form['Max Revisions']) || 3;
const comment = (form['Revision Comments'] || '').toString().trim();
const hasComment = comment.length > 0;
const canRevise = form.Decision === 'Rejected' && hasComment && revisionCount < maxRevisions;

return [{
  json: {
    ...form,
    revisionCount,
    maxRevisions,
    hasComment,
    canRevise
  }
}];

const data = $input.item.json;
const storyKey = $('Parse Story Key & Bug Text').item.json.storyKey;

let description = `*Steps to Reproduce:*\n${data['Steps to Reproduce']}\n\n`;
description += `*Expected Result:*\n${data['Expected Result']}\n\n`;
description += `*Actual Result:*\n${data['Actual Result']}\n\n`;
description += `*Severity:* ${data['Severity']}\n\n`;
if (storyKey) {
  description += `*Related Story:* ${storyKey}\n`;
}
description += `\n_This bug report was drafted by the Smart Bug Report Agent, revised ${data.revisionCount || 0} time(s), and approved by a human before creation._`;

return [{
  json: {
    title: data['Bug Title'],
    description,
    severity: data['Severity'],
    storyKey,
    revisionCount: data.revisionCount || 0
  }
}];

const created = $input.item.json;
const finalBug = $('Finalize Approved Bug').item.json;

const bugKey = created.key || created.id || 'UNKNOWN';

let md = `**Decision:** Approved\n\n**New Bug Created:** ${bugKey}\n\n`;
md += `**Title:** ${finalBug.title}\n\n`;
md += `**Severity:** ${finalBug.severity}\n\n`;
if (finalBug.storyKey) {
  md += `**Related Story:** ${finalBug.storyKey}\n\n`;
}
md += `**Revisions before approval:** ${finalBug.revisionCount}\n\n`;
md += `${finalBug.description}`;

return [{
  json: {
    output: md,
    decision: 'Approved',
    bugKey,
    storyKey: finalBug.storyKey,
    revisionCount: finalBug.revisionCount
  }
}];

const form = $input.item.json;
const payload = $('Prepare Jira Payload').item.json;

const newRevisionCount = (form.revisionCount || 0) + 1;

return [{
  json: {
    isRevision: true,
    revisionComments: form['Revision Comments'],
    previousDraft: {
      title: form['Bug Title'],
      stepsToReproduce: form['Steps to Reproduce'],
      expectedResult: form['Expected Result'],
      actualResult: form['Actual Result'],
      severity: form['Severity'],
      severityJustification: payload.severityJustification || ''
    },
    revisionCount: newRevisionCount
  }
}];

const data = $input.item.json;

let md = `**Decision:** Rejected\n\n`;

if (data.revisionCount >= data.maxRevisions) {
  md += `Maximum revision attempts (${data.maxRevisions}) reached without approval. This bug report needs manual handling outside this workflow - please review and create the Jira bug manually.\n\n`;
} else if (!data.hasComment) {
  md += `The drafted bug report was rejected with no revision comments, so it was not sent back for AI revision. No issue was created in Jira.\n\n`;
}

md += `**Last Drafted Title:** ${data['Bug Title']}\n\n`;
md += `**Last Drafted Severity:** ${data['Severity']}\n\n`;
if (data['Related Story']) {
  md += `**Related Story:** ${data['Related Story']}\n\n`;
}
md += `**Revisions used:** ${data.revisionCount} of ${data.maxRevisions}\n\n`;
md += `_To try again, start a new run with a corrected or more detailed bug description._`;

return [{
  json: {
    output: md,
    decision: 'Rejected',
    revisionCount: data.revisionCount
  }
}];
